@Component
public class BookDataLoaderRegisterer {

    @Autowired
    private BookRepository bookRepository;

    public DataLoader<Long, List<Book>> bookDataLoader() {
        return DataLoader.newDataLoader((List<Long> authorIds) -> 
            CompletableFuture.supplyAsync(() -> {
                List<Book> books = bookRepository.findByAuthorIdIn(authorIds);
                // Group books by authorId to satisfy DataLoader's mapping contract
                Map<Long, List<Book>> groupedBooks = books.stream()
                    .collect(Collectors.groupingBy(Book::getAuthorId));

                return authorIds.stream()
                    .map(id -> groupedBooks.getOrDefault(id, Collections.emptyList()))
                    .collect(Collectors.toList());
            })
        );
    }
}
